content.text:
{
  "name": "通用I2C字符液晶显示屏",
  "name_en": "Generic I2C Character LCD",
  "manufacturer": "",
  "description": "这是一种带有 I2C 转接背板的字符液晶显示模块，常见规格为 16x2 或 20x4。它通常安装在实验装置、控制箱或测量系统上，用于显示传感器读数、设备状态、菜单信息、提示文本或报警信息。",
  "description_en": "This is a character LCD module with an I2C backpack, commonly in 16x2 or 20x4 formats. It is typically used on laboratory instruments, control panels, or measurement systems to display sensor readings, device status, menu text, prompts, or alarm messages.",
  "actions": [
    {
      "action_name": "auto-lcd_backlight",
      "description": "打开或关闭液晶显示屏背光。",
      "description_en": "Turn the LCD backlight on or off."
    },
    {
      "action_name": "auto-lcd_byte",
      "description": "向液晶显示屏发送一个数据字节或命令字节。",
      "description_en": "Send a data byte or command byte to the LCD."
    },
    {
      "action_name": "auto-lcd_init",
      "description": "初始化液晶显示屏，使其进入可显示状态。",
      "description_en": "Initialize the LCD so it is ready for display operation."
    },
    {
      "action_name": "auto-lcd_string_write",
      "description": "在液晶显示屏指定行写入一段文本。",
      "description_en": "Write a text string to a specified line of the LCD."
    },
    {
      "action_name": "auto-lcd_toggle_enable",
      "description": "切换液晶显示屏使能信号以锁存传输数据。",
      "description_en": "Toggle the LCD enable signal to latch transmitted data."
    },
    {
      "action_name": "auto-lcd_write_lines",
      "description": "一次更新液晶显示屏的多行文本内容。",
      "description_en": "Update multiple lines of text on the LCD at once."
    }
  ],
  "tag_hints": [
    "I2C LCD",
    "character display",
    "16x2 LCD",
    "20x4 LCD",
    "instrument status display",
    "backlight control",
    "lab user interface"
  ]
}

